function buildSuffixArray(s) {
  const n = s.length;
  const suffixes = [];
  for (let i = 0; i < n; i++) suffixes.push({ index: i, suffix: s.slice(i) });
  suffixes.sort((a, b) => (a.suffix < b.suffix ? -1 : a.suffix > b.suffix ? 1 : 0));
  return suffixes.map(x => x.index);
}

